import math

def check_solution(a, b, c, K=2012):
    """Checks if the triple (a, b, c) satisfies the equation."""
    LHS = a**3 * (b**3 + c**3)
    RHS = K * (a * b * c + 2)
    return LHS == RHS

# --- Case a = 1 ---
print("--- Case a = 1 ---")
solutions_a1 = []
# We search for 1 <= b <= c
B_limit_a1 = 10 # Limiting b for initial search
C_limit_a1 = 50 # Limiting c for initial search

for b in range(1, B_limit_a1 + 1):
    # Start c from b
    for c in range(b, C_limit_a1 + 1):
        if check_solution(1, b, c):
            solutions_a1.append((1, b, c))

if solutions_a1:
    print("Solutions found for a=1:", solutions_a1)
else:
    print("No solutions found for a=1 in the current search range.")

# --- Case a = 2 ---
print("\n--- Case a = 2 ---")
solutions_a2 = []
# We search for 2 <= b <= c
B_limit_a2 = 5 # Limiting b for initial search, since a=2
C_limit_a2 = 50 # Limiting c for initial search

for b in range(2, B_limit_a2 + 1):
    # Start c from b
    for c in range(b, C_limit_a2 + 1):
        if check_solution(2, b, c):
            solutions_a2.append((2, b, c))

if solutions_a2:
    print("Solutions found for a=2:", solutions_a2)
else:
    print("No solutions found for a=2 in the current search range.")

